import { ChatBubble } from "march/ui"

// grup sohbeti: tepkiye basınca sayı değişir; gitmeyen mesajda "yeniden dene"
export function GroupChat() {
  let $reacts = [{ emoji: "❤️", count: 2, mine: false }]
  let $status = "failed"
  const react = (e: string) => $reacts = $reacts.map((r) => (r.emoji === e ? { ...r, mine: !r.mine, count: r.count + (r.mine ? -1 : 1) } : r))
  return <div sx={{ flex: "col", gap: 1 }}>
    <ChatBubble sender="Deniz" senderColor={2} text="Pazar koşusu 7'de!" position="single" reactions={$reacts} onReact={react} />
    <ChatBubble mine text="Ben de geliyorum" reply={{ name: "Deniz", text: "Pazar koşusu 7'de!" }} status={$status as "failed"}
      onRetry={() => $status = "sent"} position="single" edited />
  </div>
}

import { ChatBubble } from "march/ui"
import { cornerUpLeft, smilePlus } from "march/icons/lucide"

// ChatBubble'ın özellikleri: text, mine, position, time, status, sender, senderColor, reply, reactions, edited, onReact,
// onReactMenu, onReply, onRetry, labels, ticks, formatTime, replyHint, swipe, tools, reactIcon, replyIcon, class, içerik
export function ChatBubbleLab() {
  let $log = "—"
  return <div sx={{ flex: "col", gap: 1 }}>
    <ChatBubble class="lab-mine" mine text="Merhaba!" time={new Date(2026, 10, 19, 9, 41)} formatTime={(d: Date) => `${d.getHours()}.${d.getMinutes()}`}
      status="read" labels={{ read: "Görüldü" }} ticks={(st: string) => <span>{st}</span>} edited tools onReply={() => $log = "yanıt"}
      replyIcon={cornerUpLeft} replyHint={<span>↩</span>} />
    <ChatBubble class="lab-other" text="Selam" sender="Elif" senderColor={1} position="first" swipe={false}
      reactions={[{ emoji: "👍", count: 3 }]} onReact={(e: string) => $log = `tepki ${e}`} onReactMenu={() => $log = "menü"} reactIcon={smilePlus} />
    {/* reply: üstte alıntı; status="failed" ile onRetry yeniden deneme satırını gösterir */}
    <ChatBubble class="lab-fail" mine text="Akşam görüşelim" reply={{ name: "Elif", text: "Selam" }} status="failed"
      labels={{ retry: "Gitmedi · Yeniden dene" }} onRetry={() => $log = "yeniden"} />
    <ChatBubble class="lab-kids" position="last"><i>Kendi içeriğim</i></ChatBubble>
    <span class="lab-log">{$log}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ChatBubbleLab } from "./ChatBubbleLab.tsx"

// ChatBubbleLab'in testleri: kaydedince Testler sekmesinde çalışır
test("metin, gönderen ve kendi içerik çizilir", () => {
  const s = renderTest(() => <ChatBubbleLab />)
  expect(s.sees("Merhaba!")).toBe(true)
  expect(s.get(".lab-other")?.textContent).toContain("Elif")
  expect(s.get(".lab-kids")?.textContent).toContain("Kendi içeriğim")
})

test("formatTime saati kendi biçiminde yazar", () => {
  const s = renderTest(() => <ChatBubbleLab />)
  expect(s.get(".lab-mine")?.textContent).toContain("9.41")
})

test("tepki çipine basınca onReact çağrılır", async () => {
  const s = renderTest(() => <ChatBubbleLab />)
  await s.click(s.get(".lab-other button")!)
  expect(s.get(".lab-log")?.textContent).toContain("tepki")
})

test("alıntı çizilir, onRetry yeniden dener", async () => {
  const s = renderTest(() => <ChatBubbleLab />)
  expect(s.get(".lab-fail")?.textContent).toContain("Elif")
  await s.click("Gitmedi · Yeniden dene")
  expect(s.get(".lab-log")?.textContent).toBe("yeniden")
})
